/* ============================================================
   IRONLOG — powerlifting logger
   All weights stored internally in KG. Display converts.

   The entry point: index.html loads this file and it imports the rest.
   What is here is boot — the nav and top-bar handlers, the first read
   of the stored log, the rescue screen, the service worker. It is the
   last module to run, so everything it touches at load already exists.
   Where the rest lives: r&d/notes/module-split.md.
   ============================================================ */
/* imports — generated by r&d/tools/module-map.cjs --sync, not by hand */
import { openCoach } from './coach.js';
import { $, APP_VERSION, esc, iso } from './core.js';
import { loadBundledData } from './data.js';
import { DEFAULT_STATE, KEY, S, flush, freshInstall, healCustomMovements, idb, load, migrateToV2, migrationDryRun,
  migrationDryRunText, requestPersistence, runDataMigrations, save, saveTimer, setBootFailed, setState, storageStatus,
  storeGet } from './database.js';
import { openTools } from './tools.js';
import { applySkin, checkForUpdate, closeModal, go, maybeWhatsNew, modalStack, openProfile, openSettings, openWelcome,
  page, setPage, setWhatsNewArmed, toast, updateAsked, welcomeDue } from './ui.js';
/* end imports */

/* ============================================================
   BOOT
   ============================================================ */
document.querySelectorAll('#nav button[data-page]').forEach(b => b.onclick = () => go(b.dataset.page));
$('#navCoach').onclick = () => openCoach();
$('#settingsBtn').onclick = openSettings;
$('#profileBtn').onclick = () => openProfile();
$('#toolsBtn').onclick = () => openTools();
document.addEventListener('keydown', e => {
  if (e.key !== 'Escape' || !modalStack.length) return;
  const top = modalStack[modalStack.length - 1];
  if (top._guard && !top._guard()) return;
  closeModal();
});

/* Fields let go of focus when you're done with them (roadmap A5, Blast #49).
   On Android, dismissing the keyboard with Back or Done leaves the field
   focused, and tapping the background doesn't move focus either — so the
   next stray keystroke lands in the last weight or reps box. Two fixes:
   a tap on anything that isn't itself a form control blurs the field, and
   the keyboard closing (the visual viewport growing back) blurs it too. */
const isField = el => !!el && (el.matches('input:not([type=button]):not([type=submit]):not([type=checkbox]):not([type=radio]):not([type=file]), textarea, select') || el.isContentEditable);
document.addEventListener('pointerdown', e => {
  const a = document.activeElement;
  if (!isField(a)) return;
  const t = e.target;
  if (t === a || isField(t) || (t.closest && t.closest('label'))) return;
  a.blur();
}, true);
if (window.visualViewport) {
  let vvh = window.visualViewport.height;
  window.visualViewport.addEventListener('resize', () => {
    const h2 = window.visualViewport.height;
    // grew by a keyboard's worth: the keyboard went away
    if (h2 - vvh > 120 && isField(document.activeElement)) document.activeElement.blur();
    vvh = h2;
  });
}

/* First paint waits on the initial read. Without this the app would render an
   empty log for a frame and then flash the real one in over the top. */
async function bootApp() {
  /* The inline script in <head> has already put the skin on <html> from the
     localStorage mirror, so the veil can be painted in the right colours here
     and the stored setting only has to confirm it below. */
  const w98 = document.documentElement.dataset.skin === 'win98';
  const veil = document.createElement('div');
  veil.id = 'bootVeil';
  veil.style.cssText = 'position:fixed;inset:0;z-index:9999;display:grid;place-items:center;' +
    (w98 ? 'background:#000000;color:#00ff41;font:700 14px/1.4 "Cascadia Mono",Consolas,ui-monospace,monospace;letter-spacing:.08em'
         : 'background:#0d0f14;color:#8b93a7;font:500 15px/1.4 system-ui,-apple-system,sans-serif');
  veil.textContent = w98 ? 'LOADING YOUR LOG…' : 'Loading your log…';
  document.body.appendChild(veil);

  await loadBundledData();   // the shipped program's manifest (js/data.js); never fatal
  setState(await load());

  /* The mirror got the page painted; the stored state is the truth. They only
     disagree after an import or a wipe, and this is where that is settled. */
  applySkin(S.settings.skin);

  /* Spec section 8: the dry run reports first, and migration never alters a
     stored number. A name the catalogue cannot resolve becomes its own custom
     movement rather than being guessed into an existing one — the report lists
     every one so they can be remapped by hand later. */
  if ((S.schemaVersion || 1) < 2) {
    const R = migrationDryRun(S);
    console.log(migrationDryRunText(R));
    const applied = migrateToV2(S);
    if (applied.orphans.length) console.warn('migration: unresolved names became custom movements:', applied.orphans);
    save(); await flush();
  }
  if (healCustomMovements()) save();   // sets pointing at a custom exercise with no record (an older Drive restore or CSV)
  const migNotes = await runDataMigrations(S);   // bug sweep 00-B2: each once, rescue copy first
  if (Object.keys(S.migrations || {}).length) { save(); if (migNotes.length) await flush(); }

  /* No auto-install. It used to drop a personal 77-week plan and two meets into
     any empty state — every new user, and this account after "Erase all data".
     Installing is now always an explicit choice in Settings. */

  if (S.active) setPage('workout');     // resume straight into a live session
  go(page);
  /* After first paint, never before it — an update prompt must not delay the
     app opening, and it must not decide for you. */
  setTimeout(() => checkForUpdate(true), 1200);
  /* What's new, after the update check so the two never open on top of each
     other. A fresh install is already marked as seen by load(). */
  if (!freshInstall) setTimeout(() => { setWhatsNewArmed(true); maybeWhatsNew(); }, 1800);
  if (welcomeDue()) setTimeout(() => { if (welcomeDue() && !document.querySelector('.modal')) openWelcome(); }, 400);
  veil.remove();
  if (migNotes.length) setTimeout(() => toast(migNotes.join(' · '), 'green'), 2400);
  requestPersistence().then(storageStatus);
}

/* If opening the log throws — in the read, the migration or the first paint —
   the loading screen used to stay up for good, with no way to reach Export
   (bug sweep 1.3 / 2.1). Now it says so, writes nothing, and offers a copy of
   exactly what is stored. Plain DOM and inline styles: nothing here may lean
   on the parts of the app that just failed. */
async function bootRescue(err) {
  setBootFailed(true);
  clearTimeout(saveTimer);
  console.error('Ironlog could not open the log', err);
  const veil = document.getElementById('bootVeil'); if (veil) veil.remove();
  let raw = null;
  try { raw = await storeGet(KEY); } catch (e) { /* shown as nothing to save */ }
  const msg = String((err && (err.stack || err.message)) || err || 'unknown error').split('\n').slice(0, 3).join(' · ');
  const btn = 'display:block;width:100%;min-height:48px;margin:10px 0 0;padding:12px 14px;border-radius:10px;border:1px solid #3a4152;background:#1a1e28;color:#e8ecf3;font:600 15px/1.2 system-ui,-apple-system,sans-serif';
  const box = document.createElement('div');
  box.id = 'bootRescue';
  box.setAttribute('role', 'alertdialog'); box.setAttribute('aria-labelledby', 'brTitle'); box.setAttribute('aria-describedby', 'brBody');
  box.style.cssText = 'position:fixed;inset:0;z-index:9999;overflow:auto;padding:28px 18px;background:#0d0f14;color:#e8ecf3;font:500 15px/1.5 system-ui,-apple-system,sans-serif';
  box.innerHTML = `<div style="max-width:460px;margin:0 auto">
    <h1 id="brTitle" style="font-size:20px;margin:0 0 10px">Ironlog couldn't open your log</h1>
    <p id="brBody" style="margin:0 0 6px">${raw ? 'Your data is still stored on this phone and nothing has been deleted or changed. Save a copy of it first, then try again.' : 'Nothing could be read from this phone\'s storage. Try again; if this keeps happening, restore from your last backup.'}</p>
    ${raw ? `<button id="brSave" style="${btn};background:#ff5c35;border-color:#ff5c35;color:#111">Save a copy of my data</button>` : ''}
    <button id="brRetry" style="${btn}">Try again</button>
    <button id="brFresh" style="${btn};color:#ff8f8f">Start with an empty log…</button>
    <p style="margin:16px 0 4px;color:#8b93a7;font-size:13px">What went wrong (v${esc(APP_VERSION)}):</p>
    <p style="margin:0;color:#8b93a7;font:12px/1.4 ui-monospace,Consolas,monospace;word-break:break-word">${esc(msg)}</p>
  </div>`;
  document.body.appendChild(box);
  const q = id => box.querySelector('#' + id);
  let saved = false;
  if (q('brSave')) q('brSave').onclick = () => {
    const a = document.createElement('a');
    a.href = URL.createObjectURL(new Blob([raw], { type: 'application/json' }));
    a.download = `ironlog-rescue-${iso()}.json`;
    a.click();
    setTimeout(() => URL.revokeObjectURL(a.href), 4000);
    saved = true;
    q('brSave').textContent = 'Saved — check your downloads';
  };
  q('brRetry').onclick = () => location.reload();
  q('brFresh').onclick = async () => {
    if (!confirm(raw && !saved ? 'You haven\'t saved a copy yet. Start with an empty log anyway? What is stored now is set aside on this phone, not deleted, but it can only be got back with help.'
      : 'Start with an empty log? What is stored now is set aside on this phone, not deleted.')) return;
    try {
      const fresh = structuredClone(DEFAULT_STATE); fresh.schemaVersion = 2; fresh.settings.lastSeenVersion = APP_VERSION;
      if (!raw) {
        /* Storage didn't answer, so the real log may still be in there. Ask
           once more; if it's still silent, the empty log goes to the fallback
           store only — IndexedDB is left alone, and whatever it holds is what
           opens again the day it answers. */
        let again = null, silent = false;
        try { again = await idb('readonly', st => st.get(KEY)); } catch (e) { silent = true; }
        if (again != null) return location.reload();
        if (silent) { localStorage.setItem(KEY, JSON.stringify(fresh)); return location.reload(); }
      }
      if (raw) await idb('readwrite', st => st.put(raw, KEY + '.rescue'));   // set aside, never thrown away
      await idb('readwrite', st => st.put(JSON.stringify(fresh), KEY));
      location.reload();
    } catch (e) { alert('Could not write to storage: ' + ((e && e.message) || e)); }
  };
  q(raw ? 'brSave' : 'brRetry').focus();
}
function boot() { return bootApp().catch(bootRescue); }

boot();

/* ---------------- offline + updates ----------------
   The service worker caches the app so it opens with no signal at all. When a
   new version is deployed it installs in the background and swaps in on the
   next launch — never mid-session, which would lose the sets on screen. */
if ('serviceWorker' in navigator) {
  let reloading = false;
  /* On a first install the worker takes control of a page that had none. That
     isn't an update, and reloading for it cut the welcome sheet off a second
     after it opened (bug sweep 4.6). */
  const hadController = !!navigator.serviceWorker.controller;
  navigator.serviceWorker.addEventListener('controllerchange', () => {
    if (reloading || (!hadController && !updateAsked)) return;
    reloading = true;
    // the last edit is written before the page goes (bug sweep 1.7)
    Promise.resolve().then(flush).catch(() => {}).then(() => location.reload());
  });

  window.addEventListener('load', () => {
    navigator.serviceWorker.register('sw.js').then(reg => {
      reg.addEventListener('updatefound', () => {
        const sw = reg.installing;
        if (!sw) return;
        sw.addEventListener('statechange', () => {
          if (sw.state !== 'installed' || !navigator.serviceWorker.controller) return;
          /* Mid-workout, or with any sheet open (an edit, a check-in, a test in
             progress): leave it waiting. Restarting there threw away whatever
             was typed and not yet saved (bug sweep 1.7). */
          const busy = () => !!(S && S.active) || modalStack.length > 0 || !!document.getElementById('bootRescue');
          if (busy()) {
            toast('Update downloaded — it will apply next time you open the app');
            return;
          }
          toast('Update ready — restarting', 'green');
          setTimeout(() => { if (!busy() && reg.waiting) reg.waiting.postMessage({ type: 'SKIP_WAITING' }); }, 1400);
        });
      });
      setInterval(() => reg.update(), 60 * 60 * 1000);
    }).catch(() => {});
  });
}
